.tb-time {
  box-sizing: border-box;
  height: 100%;
  width: 100%;
  padding: 16px;
  background: #A7C7E7;
  color: #ffffff;
  border-radius: 20px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 10px;
  font-family: inherit;
}

.tb-time .title {
  text-align: center;
  font-size: 16px;
  font-weight: 600;
  line-height: 20px;
}

.tb-time .row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);   /* 3 data in one row */
  gap: 12px;
}

.tb-time .cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  text-align: center;
  min-width: 0;
}

.tb-time .label,
.tb-time .value {
  display: block;
  width: 100%;
}

.tb-time .label {
  height: 16px;
  line-height: 16px;
  font-size: 12px;
  opacity: 0.9;
}

.tb-time .value {
  height: 30px;
  line-height: 30px;
  font-size: 22px;
  font-weight: 600;
}

.tb-led {
  box-sizing: border-box;
  height: 100%;
  width: 100%;
  padding: 16px;
  background: none;                 /* no background */
  color: #ffffff;
  border-radius: 0;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: center;
  gap: 16px;
  font-family: inherit;
}

/* LED on the left */
.tb-led .led {
  position: relative;
  flex: 0 0 38px;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.6), 0 0 12px rgba(0, 0, 0, 0.25);
}

.tb-led .led span {
  position: absolute;
  top: 0; right: 0; bottom: 0; left: 0;
  border-radius: 50%;
  transition: opacity 0.3s;
}

.tb-led .led .g { background: #2ecc71; }   /* green */
.tb-led .led .y { background: #f1c40f; }   /* yellow */
.tb-led .led .r { background: #e74c3c; }   /* red */

/* Text on the right: all three texts share one grid cell */
.tb-led .txt {
  display: grid;
  min-width: 0;
}

.tb-led .txt span {
  grid-area: 1 / 1;
  font-size: 22px;
  font-weight: 600;
  line-height: 44px;                /* same height as the LED */
  white-space: nowrap;
  transition: opacity 0.3s;
}

.tb-row {
  box-sizing: border-box;
  height: 100%;
  width: 100%;
  padding: 16px;
  background: #A7C7E7;
  color: #ffffff;
  border-radius: 20px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: center;          /* centers the whole block; cells are now equal height */
  gap: 12px;
  font-family: inherit;
}

.tb-row .cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;  /* align from the top, not the middle */
  text-align: center;
  min-width: 0;
}

.tb-row .label,
.tb-row .value,
.tb-row .unit {
  display: block;
  width: 100%;
}

.tb-row .label {
  height: 16px;                 /* fixed height for the name */
  line-height: 16px;
  font-size: 12px;
  opacity: 0.9;
}

.tb-row .value {
  height: 30px;                 /* fixed height for the value */
  line-height: 30px;
  font-size: 22px;
  font-weight: 600;
}

.tb-row .unit {
  height: 16px;                 /* reserved even when empty */
  line-height: 16px;
  font-size: 12px;
  opacity: 0.9;
}

.tb-seven-adm {
  box-sizing: border-box;
  height: 100%;
  width: 100%;
  padding: 0;
  background: none;
  display: grid;
  grid-template-columns: repeat(7, 1fr);   /* 7 equal columns */
  gap: 0;
  align-items: start;
  font-family: inherit;
}

.tb-seven-adm .cell {
  box-sizing: border-box;
  padding: 0 2px;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 0;
}

/* title: scales with the column width, no background */
.tb-seven-adm .ttl {
  display: block;
  width: 100%;
  height: auto;
  background: none;
}

.tb-seven-adm .ttl text {
  fill: #1b1f3b;
  font-weight: 600;
  font-family: inherit;
}

/* value and offline text share one grid cell */
.tb-seven-adm .val {
  height: 30px;
  width: 100%;
  display: grid;
  align-items: center;
  justify-items: center;
  color: #1b1f3b;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

.tb-seven-adm .val span {
  grid-area: 1 / 1;
  transition: opacity 0.3s;
}

.tb-seven-adm .val .off {
  color: #e74c3c;
  opacity: 0;                               /* hidden unless the inline value says otherwise */
}

