  color: #ffffff;
  border-radius: 20px;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  align-items: center;          /* centers the whole block; cells are now equal height */
  gap: 12px;
  font-family: inherit;
}

.tb-row .cell {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;  /* align from the top, not the middle */
  text-align: center;
  min-width: 0;
}

.tb-row .label,
.tb-row .value,
.tb-row .unit {
  display: block;
  width: 100%;
}

.tb-row .label {
  height: 16px;                 /* fixed height for the name */
  line-height: 16px;
  font-size: 12px;
  opacity: 0.9;
}

.tb-row .value {
  height: 30px;                 /* fixed height for the value */
  line-height: 30px;
  font-size: 22px;
  font-weight: 600;
}

.tb-row .unit {
  height: 16px;                 /* reserved even when empty */
  line-height: 16px;
  font-size: 12px;
  opacity: 0.9;
}

.tb-seven-adm {
  box-sizing: border-box;
  height: 100%;
  width: 100%;
  padding: 0;
  background: none;
  display: grid;
  grid-template-columns: repeat(7, 1fr);   /* 7 equal columns */
  gap: 0;
  align-items: start;
  font-family: inherit;
}

.tb-seven-adm .cell {
  box-sizing: border-box;
  padding: 0 2px;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 0;
}

/* title: scales with the column width, no background */
.tb-seven-adm .ttl {
  display: block;
  width: 100%;
  height: auto;
  background: none;
}

.tb-seven-adm .ttl text {
  fill: #1b1f3b;
  font-weight: 600;
  font-family: inherit;
}

/* value and offline text share one grid cell */
.tb-seven-adm .val {
  height: 30px;
  width: 100%;
  display: grid;
  align-items: center;
  justify-items: center;
  color: #1b1f3b;
  font-size: 14px;
  font-weight: 600;
  white-space: nowrap;
}

.tb-seven-adm .val span {
  grid-area: 1 / 1;
  transition: opacity 0.3s;
}

.tb-seven-adm .val .off {
  color: #e74c3c;
  opacity: 0;                               /* hidden unless the inline value says otherwise */
}

.tb-flow {
  box-sizing: border-box;
  height: 100%;
  width: 100%;
  padding: 16px;
  background: #A7C7E7;
  color: #ffffff;
  border-radius: 20px;
  display: flex;
  flex-direction: column;
  font-family: inherit;
}

.tb-flow .title {
  text-align: center;
  font-size: 16px;
  font-weight: 600;
  line-height: 20px;
  margin-bottom: 8px;
}

.tb-flow .row {
  flex: 1 1 0;                              /* the 7 rows share the height equally */
  min-height: 0;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: 8px;
}

.tb-flow .name {
  font-size: 12px;
  opacity: 0.9;
  white-space: nowrap;
}

/* value and offline text share one grid cell */
.tb-flow .val {
  display: grid;
  justify-items: end;
  font-size: 18px;
  font-weight: 600;
  white-space: nowrap;
}

.tb-flow .val span {
  grid-area: 1 / 1;
  transition: opacity 0.3s;
}

.tb-flow .val .off {
  color: #e74c3c;
  opacity: 0;                               /* hidden unless the inline value says otherwise */
}
